        int plusPos = expression.indexOf('+');
        String L = expression.substring(0, plusPos);
        String R = expression.substring(plusPos + 1);
        long minVal = Long.MAX_VALUE;
        String bestExpr = "";
        for (int i = 0; i < L.length(); i++) {
            long m1 = i > 0 ? Long.parseLong(L.substring(0, i)) : 1;
            long a = Long.parseLong(L.substring(i));
            for (int j = 1; j <= R.length(); j++) {
                long b = Long.parseLong(R.substring(0, j));
                long m2 = j < R.length() ? Long.parseLong(R.substring(j)) : 1;
                long val = m1 * (a + b) * m2;
                if (val < minVal) {
                    minVal = val;
                    bestExpr = L.substring(0, i) + "(" + L.substring(i) + "+" + R.substring(0, j) + ")" + R.substring(j);
                }
            }
        }
        return bestExpr;
    }
}

