var minimizeResult = function(expression) {
    const [L, R] = expression.split('+');
    let minVal = Infinity;
    let bestExpr = '';
    for (let i = 0; i < L.length; i++) {
        const m1 = i > 0 ? parseInt(L.slice(0, i), 10) : 1;
        const a = parseInt(L.slice(i), 10);
        for (let j = 1; j <= R.length; j++) {
            const b = parseInt(R.slice(0, j), 10);
            const m2 = j < R.length ? parseInt(R.slice(j), 10) : 1;
            const val = m1 * (a + b) * m2;
            if (val < minVal) {
                minVal = val;
                bestExpr = `${L.slice(0, i)}(${L.slice(i)}+${R.slice(0, j)})${R.slice(j)}`;
            }
        }
    }
    return bestExpr;
};
